const $=s=>document.querySelector(s);let productsETag='',categoriesETag='',editingOriginal=null;let products=[],inquiries=[],payments=[],bankTransfers=[],crmProfiles=[],settings={},categories=[],editingId=null,setupRequired=false,selectedMajor=0;
async function api(url,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(url==='/api/products'&&opts.method==='PUT'&&productsETag)headers['If-Match']=productsETag;if(url==='/api/categories'&&opts.method==='PUT'&&categoriesETag)headers['If-Match']=categoriesETag;const r=await fetch(url,{...opts,headers});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'Request failed');if(url==='/api/products'&&['GET','PUT'].includes(opts.method||'GET'))productsETag=r.headers.get('ETag')||'';if(url==='/api/categories'&&['GET','PUT'].includes(opts.method||'GET'))categoriesETag=r.headers.get('ETag')||'';return d}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function slug(s){return s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'product'}function toast(m){$('#toast').textContent=m;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
async function init(){const s=await api('/api/status');setupRequired=s.setupRequired;window.kejunSetupTokenRequired=!!s.setupTokenRequired;$('#status').textContent=s.authenticated?'Connected':'Sign in required';if(!s.authenticated){$('#gate').classList.remove('hidden');$('#gateTitle').textContent=setupRequired?'Create your admin password':'Sign in to Qingke CMS';$('#gateCopy').textContent=setupRequired?'Create the first admin password for this website.':'Sign in to manage categories, product groups, images and specifications.';$('#gateSubmit').textContent=setupRequired?'Create password':'Sign in';$('#passwordLabel').innerHTML=(setupRequired?'Create admin password':'Admin password')+'<input id="password" type="password" minlength="12" required autocomplete="current-password" placeholder="At least 12 characters">';$('#gateHint').textContent=setupRequired?'Use at least 12 characters, ideally a unique passphrase.':'Password protected.';const oldTokenField=document.getElementById('setupTokenField');if(oldTokenField)oldTokenField.remove();if(setupRequired&&window.kejunSetupTokenRequired){const field=document.createElement('label');field.id='setupTokenField';field.textContent='首次初始化密钥（Render ADMIN_SETUP_TOKEN）';const input=document.createElement('input');input.id='setupToken';input.type='password';input.required=true;input.autocomplete='off';input.placeholder='请输入在 Render 设置的初始化密钥';field.appendChild(input);$('#gateForm').insertBefore(field,$('#gateSubmit'));}document.querySelectorAll('.side .nav,.sidebottom #logout').forEach(e=>e.classList.add('hidden'));return}$('#gate').classList.add('hidden');document.querySelectorAll('.side .nav').forEach(e=>e.classList.remove('hidden'));$('#logout').classList.remove('hidden');await loadAll()}
