async function loadAll(){[products,inquiries,settings,categories,payments]=await Promise.all([api('/api/products').catch(()=>[]),api('/api/inquiries').catch(()=>[]),api('/api/settings').catch(()=>({})),api('/api/categories').catch(()=>[]),api('/api/payments').catch(()=>[])]);renderProducts();fillSettings();renderTaxonomy();renderPayments();renderBankTransfers();$('#status').textContent='Connected'}
document.querySelectorAll('.nav[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.tab').forEach(x=>x.classList.add('hidden'));$('#'+b.dataset.tab+'Tab').classList.remove('hidden');$('#heading').textContent=b.textContent.trim().replace(/\d+/g,'').trim();if(b.dataset.tab==='inquiries')loadInquiries();if(b.dataset.tab==='crm')loadCRM();if(b.dataset.tab==='payments')loadPayments();if(b.dataset.tab==='bankTransfers')loadBankTransfers();if(b.dataset.tab==='categories')renderTaxonomy();if(b.dataset.tab==='emailOutbox')loadEmailOutbox()}));
function renderProducts(){renderTranslationCoverage();const term=$('#search').value.toLowerCase(),cat=$('#categoryFilter').value;$('#categoryFilter').innerHTML='<option value="">All categories</option>'+categories.map(c=>`<option ${cat===c.name?'selected':''}>${esc(c.name)}</option>`).join('');const list=products.filter(p=>(!cat||p.category===cat)&&(`${p.name} ${p.model||''} ${p.description} ${p.category} ${p.subcategory} ${p.group} ${Object.entries(p.specs||{}).map(([k,v])=>k+' '+v).join('')}`.toLowerCase().includes(term)));$('#productCount').textContent=`${list.length} products`;$('#productRows').innerHTML=list.map(p=>`<tr><td><input type="checkbox" class="product-bulk-check" data-product-id="${esc(p.id)}" aria-label="选择 ${esc(p.name)}"></td><td><img src="/${esc(String(p.image||'assets/p4_i1_400x400.png').replace(/^\//,''))}" alt="${esc(p.name||p.model||'Product')}" style="width:56px;height:56px;object-fit:contain;border:1px solid #e2e8f0;border-radius:7px;background:#fff" onerror="this.onerror=null;this.src='/assets/p4_i1_400x400.png'"></td><td><div class="prodname">${esc(p.name)}</div><div class="subtext">${esc(p.group||'')} · ${esc(p.subcategory||'')}</div></td><td>${esc(p.category)}</td><td>${Object.entries(p.specs||{}).slice(0,3).map(([k,v])=>`<span class="spec">${esc(k)}: ${esc(v)}</span>`).join('')}</td><td><span class="badge ${p.published===false?'off':''}">${p.published===false?'Draft':'Published'}</span></td><td><div class="actions"><button class="smallbtn" data-edit="${esc(p.id)}">Edit</button><button class="smallbtn danger" data-delete="${esc(p.id)}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No products match this filter.</td></tr>';$('#productRows').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openProduct(products.find(p=>p.id===b.dataset.edit)));$('#productRows').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.delete));$('#newCount').textContent=inquiries.filter(i=>i.status==='New').length||''}
$('#search').oninput=renderProducts;$('#categoryFilter').onchange=renderProducts;$('#addProduct').onclick=()=>openProduct();

const COVERAGE_LANGUAGES=[['zh-CN','简体中文'],['es','西班牙语'],['fr','法语'],['de','德语'],['pt','葡萄牙语'],['ru','俄语'],['ar','阿拉伯语'],['ko','韩语'],['ja','日语']];
function translationIsComplete(product,lang){const t=product?.translations?.[lang];return !!(t&&typeof t==='object'&&String(t.name||'').trim()&&String(t.description||'').trim())}
function renderTranslationCoverage(){const host=$('#translationCoverage');if(!host)return;const total=products.length;host.innerHTML=COVERAGE_LANGUAGES.map(([lang,label])=>{const complete=products.filter(p=>translationIsComplete(p,lang)).length;const pct=total?Math.round(complete/total*100):0;return `<div class="tax-card" style="min-width:130px;flex:1;padding:10px"><strong>${esc(label)}</strong><div style="font-size:20px;font-weight:700;margin:5px 0">${complete}/${total}</div><div class="subtext">名称+描述完成 ${pct}%</div><div style="height:5px;background:#e6ebf1;border-radius:5px;margin-top:8px;overflow:hidden"><div style="height:100%;width:${pct}%;background:#26734d"></div></div></div>`}).join('');const missing=products.reduce((n,p)=>n+COVERAGE_LANGUAGES.filter(([lang])=>!translationIsComplete(p,lang)).length,0);$('#translationCoverageNote').textContent=total?`当前 ${total} 个产品；共 ${missing} 项“语言-产品”缺少完整的名称或描述。未填写的字段会回退到默认内容。这里仅统计名称和描述，不代表技术参数、邮件和结账页面已完整翻译。`:'暂无产品数据。';renderSpecTranslationCoverage()}
function specTranslationIsComplete(product,lang,key){const entry=product?.translations?.[lang]?.specs?.[key];return !!(entry&&typeof entry==='object'&&String(entry.name||'').trim()&&String(entry.value||'').trim())}
function renderSpecTranslationCoverage(){const host=$('#specTranslationCoverage');if(!host)return;let total=0;for(const p of products)total+=Object.keys(p.specs||{}).length;host.innerHTML=COVERAGE_LANGUAGES.map(([lang,label])=>{let complete=0;for(const p of products)for(const key of Object.keys(p.specs||{}))if(specTranslationIsComplete(p,lang,key))complete++;const pct=total?Math.round(complete/total*100):0;return `<div class="tax-card" style="min-width:130px;flex:1;padding:10px"><strong>${esc(label)}</strong><div style="font-size:20px;font-weight:700;margin:5px 0">${complete}/${total}</div><div class="subtext">参数名称+值完成 ${pct}%</div><div style="height:5px;background:#e6ebf1;border-radius:5px;margin-top:8px;overflow:hidden"><div style="height:100%;width:${pct}%;background:#26734d"></div></div></div>`}).join('');let missing=0;for(const p of products)for(const key of Object.keys(p.specs||{}))missing+=COVERAGE_LANGUAGES.filter(([lang])=>!specTranslationIsComplete(p,lang,key)).length;const note=$('#specTranslationCoverageNote');if(note)note.textContent=total?`当前 ${total} 个原始参数项；${missing} 项“语言-产品-参数”缺少完整名称或值翻译。数字、量程、精度及单位请人工核对；缺失译文会回退到原始参数。`:'暂无产品技术参数。'}
function exportMissingSpecTranslations(){const rows=[['Product ID','Default product name','Language code','Language','Original parameter name','Original parameter value','Missing fields','Translated parameter name','Translated parameter value']];for(const p of products){for(const [lang,label] of COVERAGE_LANGUAGES){const translated=p?.translations?.[lang]?.specs||{};for(const [key,value] of Object.entries(p.specs||{})){const entry=translated[key]&&typeof translated[key]==='object'?translated[key]:{};const missing=[];if(!String(entry.name||'').trim())missing.push('name');if(!String(entry.value||'').trim())missing.push('value');if(missing.length)rows.push([p.id||'',p.name||'',lang,label,key,value,missing.join('; '),entry.name||'',entry.value||'']);}}}downloadTranslationCsv(rows,'kejun-missing-parameter-translations.csv');toast('已导出缺失参数翻译清单。')}
$('#exportMissingSpecTranslations')?.addEventListener('click',exportMissingSpecTranslations);
function exportMissingTranslations(){const rows=[['Product ID','Default product name','Language code','Language','Missing fields']];for(const p of products){for(const [lang,label] of COVERAGE_LANGUAGES){const t=p?.translations?.[lang]||{};const missing=[];if(!String(t.name||'').trim())missing.push('name');if(!String(t.description||'').trim())missing.push('description');if(missing.length)rows.push([p.id||'',p.name||'',lang,label,missing.join('; ')]);}}const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='kejun-product-translation-gaps.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('已导出多语言缺失清单。')}
$('#exportMissingTranslations')?.addEventListener('click',exportMissingTranslations);
const TRANSLATION_IMPORT_FIELDS=['name','description','category','subcategory','group','specs'];
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function downloadTranslationCsv(rows,filename){const csv='\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function exportTranslationTemplate(){const rows=[['Product ID','Default product name','Language code','Language','Field','Translation']];for(const p of products){for(const [lang,label] of COVERAGE_LANGUAGES){const t=p?.translations?.[lang]||{};for(const field of TRANSLATION_IMPORT_FIELDS){if(field==='specs'){const keys=Object.keys(p.specs||{});const ts=t.specs&&typeof t.specs==='object'?t.specs:{};const incomplete=keys.some(k=>{const v=ts[k];return !v||typeof v!=='object'||!String(v.name||'').trim()||!String(v.value||'').trim()});if(keys.length&&incomplete){const specDraft=Object.fromEntries(keys.map(k=>[k,{name:ts[k]?.name||'',value:ts[k]?.value||''}]));rows.push([p.id||'',p.name||'',lang,label,'specs',JSON.stringify(specDraft)]);}}else if(!String(t[field]||'').trim())rows.push([p.id||'',p.name||'',lang,label,field,'']);}}}downloadTranslationCsv(rows,'kejun-translation-review-template.csv');toast('已导出翻译模板。请只填写 Translation 列，审核后再导入。')}
$('#exportTranslationTemplate')?.addEventListener('click',exportTranslationTemplate);
function parseCsv(text){const input=String(text||'').replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<input.length;i++){const c=input[i];if(quoted){if(c==='"'&&input[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"'&&cell==='')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&input[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV 文件包含未闭合的引号，请用 WPS/Excel 重新保存。');if(cell!==''||row.length){row.push(cell);if(row.some(v=>v.trim()))rows.push(row)}return rows}
async function importTranslationCsv(file){if(!file)return;const raw=await file.text();const rows=parseCsv(raw);if(rows.length<2)throw Error('CSV 没有可导入的数据。');const headers=rows[0].map(x=>x.trim().toLowerCase());const idx=Object.fromEntries(['product id','language code','field','translation'].map(k=>[k,headers.indexOf(k)]));if(Object.values(idx).some(i=>i<0))throw Error('CSV 列名不正确。请使用后台导出的“翻译模板”，不要改动列标题。');const byId=new Map(products.map(p=>[String(p.id),p]));const changes=new Map();let skipped=0,invalid=0;for(const row of rows.slice(1)){const id=String(row[idx['product id']]||'').trim(),lang=String(row[idx['language code']]||'').trim(),field=String(row[idx.field]||'').trim().toLowerCase(),value=String(row[idx.translation]||'').trim();if(!value){skipped++;continue}if(!byId.has(id)||!COVERAGE_LANGUAGES.some(([code])=>code===lang)||!TRANSLATION_IMPORT_FIELDS.includes(field)){invalid++;continue}if(value.length>20000){invalid++;continue}const key=id+'\u0000'+lang;const entry=changes.get(key)||{product:byId.get(id),lang,values:{}};entry.values[field]=value;changes.set(key,entry)}if(!changes.size)throw Error(`没有可导入的有效翻译。跳过空行 ${skipped} 行；无效行 ${invalid} 行。`);for(const [key,entry] of changes){if(entry.values.specs){try{const parsed=JSON.parse(entry.values.specs);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error();entry.values.specs=parsed}catch{invalid++;delete entry.values.specs}}if(!Object.keys(entry.values).length)changes.delete(key)}if(!changes.size)throw Error(`没有可导入的有效翻译。跳过空行 ${skipped} 行；无效行 ${invalid} 行。`);const preview=[...changes.values()].reduce((n,x)=>n+Object.keys(x.values).length,0);if(!confirm(`导入预览：将更新 ${changes.size} 个“产品-语言”组合，共 ${preview} 个翻译字段。技术参数字段必须是 JSON，格式为 {"原始参数名":{"name":"翻译后的参数名","value":"翻译后的参数值"}}。请保持数字、量程、精度和单位准确。空白字段不会覆盖已有内容。无效行 ${invalid} 行，空白行 ${skipped} 行。确认继续吗？`))return;const next=products.map(p=>({...p,translations:p.translations&&typeof p.translations==='object'?{...p.translations}:{}}));for(const {product,lang,values} of changes.values()){const target=next.find(p=>String(p.id)===String(product.id));target.translations[lang]={...(target.translations[lang]&&typeof target.translations[lang]==='object'?target.translations[lang]:{}),...values}}await api('/api/products',{method:'PUT',body:JSON.stringify(next)});products=next;renderProducts();toast(`翻译导入成功：${preview} 个字段；无效行 ${invalid} 行。`)}
$('#importTranslationCsv')?.addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';try{await importTranslationCsv(file)}catch(err){alert('导入失败：'+err.message)}});
function categoryOptions(selected){return categories.map(c=>`<option value="${esc(c.name)}" ${c.name===selected?'selected':''}>${esc(c.name)}</option>`).join('')}
function updateSubcategoryOptions(selectedCategory,selectedSub){const c=categories.find(x=>x.name===selectedCategory);$('#productForm').elements.subcategory.innerHTML=(c?.subcategories||[]).map(s=>`<option value="${esc(s)}" ${s===selectedSub?'selected':''}>${esc(s)}</option>`).join('');if(!c?.subcategories?.length)$('#productForm').elements.subcategory.innerHTML='<option value="General">General</option>'}
function renderSpecRows(specs={}){$('#specEditor').innerHTML=Object.entries(specs).map(([k,v])=>specRow(k,v)).join('')||specRow('','');$('#specEditor').querySelectorAll('[data-remove-spec]').forEach(b=>b.onclick=()=>b.closest('.spec-edit-row').remove())}function specRow(k='',v=''){return `<div class="spec-edit-row"><input data-spec-key value="${esc(k)}" placeholder="Parameter name (e.g. Range)"><input data-spec-value value="${esc(v)}" placeholder="Value (e.g. 0–10 bar)"><button type="button" class="smallbtn danger" data-remove-spec>×</button></div>`}
const PRODUCT_LANGUAGES=[['zh-CN','简体中文'],['es','西班牙语'],['fr','法语'],['de','德语'],['pt','葡萄牙语'],['ru','俄语'],['ar','阿拉伯语'],['ko','韩语'],['ja','日语']];
function renderTranslationEditor(translations={},rawSpecs={}){const host=$('#translationEditor');if(!host)return;const specKeys=Object.keys(rawSpecs||{});host.innerHTML=PRODUCT_LANGUAGES.map(([lang,label])=>{const t=translations[lang]&&typeof translations[lang]==='object'?translations[lang]:{};const trSpecs=t.specs&&typeof t.specs==='object'?t.specs:{};const specRows=specKeys.map(originalKey=>{const current=trSpecs[originalKey];const obj=current&&typeof current==='object'?current:{name:'',value:typeof current==='string'?current:''};return `<div class="translation-spec-row full"><strong>${esc(originalKey)} <span class="subtext">/ 原始值：${esc(rawSpecs[originalKey])}</span></strong><label>参数名称翻译<input data-tr-lang="${lang}" data-tr-spec-key="${esc(originalKey)}" data-tr-spec-part="name" value="${esc(obj.name||'')}" placeholder="留空则使用原始参数名"></label><label>参数值翻译<input data-tr-lang="${lang}" data-tr-spec-key="${esc(originalKey)}" data-tr-spec-part="value" value="${esc(obj.value||'')}" placeholder="留空则使用原始参数值"></label></div>`}).join('');return `<details class="translation-language"><summary>${esc(label)}（${esc(lang)}）</summary><div class="translation-grid">${[['name','产品名称'],['description','产品描述'],['category','产品分类'],['subcategory','产品子分类'],['group','产品分组']].map(([key,title])=>`<label>${title}<input data-tr-lang="${lang}" data-tr-key="${key}" value="${esc(t[key]||'')}" placeholder="留空则使用英文默认内容"></label>`).join('')}<div class="full"><strong>技术参数逐项翻译</strong><p class="product-toolbar-note">每个已填写的原始参数都会显示在这里。可翻译参数名称和文字值；数值、量程、精度、单位必须保持准确。未填写的翻译会自动显示原始参数。</p>${specRows||'<p class="product-toolbar-note">请先在下方添加并保存原始技术参数，再编辑其翻译。</p>'}</div></div></details>`}).join('')}
function collectProductTranslations(existing={}){const out=JSON.parse(JSON.stringify(existing&&typeof existing==='object'?existing:{}));for(const [lang] of PRODUCT_LANGUAGES){const entries=[...document.querySelectorAll(`[data-tr-lang="${lang}"][data-tr-key]`)];const t={...(out[lang]&&typeof out[lang]==='object'?out[lang]:{})};for(const el of entries){const key=el.dataset.trKey,value=el.value.trim();if(value)t[key]=value;else delete t[key]}const specInputs=[...document.querySelectorAll(`[data-tr-lang="${lang}"][data-tr-spec-key]`)];const translatedSpecs={...(t.specs&&typeof t.specs==='object'?t.specs:{})};for(const el of specInputs){const key=el.dataset.trSpecKey,part=el.dataset.trSpecPart,value=el.value.trim();const row={...(translatedSpecs[key]&&typeof translatedSpecs[key]==='object'?translatedSpecs[key]:{})};if(value)row[part]=value;else delete row[part];if(Object.keys(row).length)translatedSpecs[key]=row;else delete translatedSpecs[key]}if(Object.keys(translatedSpecs).length)t.specs=translatedSpecs;else delete t.specs;if(Object.keys(t).length)out[lang]=t;else delete out[lang]}return out}
async function generateTranslationDrafts(){const status=$('#translationDraftStatus'),button=$('#generateTranslationDrafts'),f=$('#productForm');const specs={};$('#specEditor').querySelectorAll('.spec-edit-row').forEach(r=>{const k=r.querySelector('[data-spec-key]').value.trim(),v=r.querySelector('[data-spec-value]').value.trim();if(k&&v)specs[k]=v});const product={name:f.elements.name.value.trim(),description:f.elements.description.value.trim(),category:f.elements.category.value,subcategory:f.elements.subcategory.value,group:f.elements.group.value.trim(),specs};if(!product.name||!product.description){status.textContent='请先填写产品名称和描述。';return}button.disabled=true;const oldLabel=button.textContent;button.textContent='正在翻译…';status.textContent='正在请求翻译服务，检查所有目标语言和技术参数；此时尚未保存。';try{const result=await api('/api/admin/translation-drafts',{method:'POST',body:JSON.stringify({product,languages:PRODUCT_LANGUAGES.map(x=>x[0])})});let filled=0,alreadyPresent=0,missing=0,total=0;for(const [lang,t] of Object.entries(result.drafts||{})){for(const [key,value] of Object.entries(t)){if(key==='specs')continue;total++;const el=[...document.querySelectorAll(`[data-tr-lang="${lang}"][data-tr-key]`)].find(x=>x.dataset.trKey===key);if(el&&value){if(!el.value.trim()){el.value=String(value);filled++}else alreadyPresent++}else missing++}for(const [specKey,parts] of Object.entries(t.specs||{})){for(const [part,value] of Object.entries(parts||{})){total++;const el=[...document.querySelectorAll(`[data-tr-lang="${lang}"][data-tr-spec-key]`)].find(x=>x.dataset.trSpecKey===specKey&&x.dataset.trSpecPart===part);if(el&&value){if(!el.value.trim()){el.value=String(value);filled++}else alreadyPresent++}else missing++}}}if(!filled&&!alreadyPresent){status.textContent='翻译服务未返回可保存的翻译内容，产品未修改。';return}status.textContent=`翻译结果检查：${total} 项字段，本次填入 ${filled} 项，保留已有译文 ${alreadyPresent} 项，未返回 ${missing} 项。正在自动保存产品…`;const saved=await saveProductForm();if(saved){const summary=`自动翻译并保存成功：本次填入 ${filled} 项，保留已有译文 ${alreadyPresent} 项，未返回 ${missing} 项。请查看翻译覆盖率统计确认完成情况。`;status.textContent=summary;toast(summary)}else{status.textContent='翻译已生成，但产品未保存：请根据表单中的错误提示修正必填项后重试。';toast('翻译已生成，但未保存；请查看表单错误提示。')}}catch(err){status.textContent=`自动翻译未完成：${err.message}。本次不会报告为成功；请检查翻译服务配置后重试。`;toast('自动翻译失败，未确认保存成功：'+err.message)}finally{button.disabled=false;button.textContent=oldLabel}}const providerCheckButton=$('#checkTranslationProvider');if(providerCheckButton)providerCheckButton.addEventListener('click',async()=>{const status=$('#translationDraftStatus');providerCheckButton.disabled=true;status.textContent='正在测试翻译服务连接……';try{const result=await api('/api/admin/translation-provider-check',{method:'POST',body:JSON.stringify({})});status.textContent=result.message||'连接测试完成。';toast(status.textContent)}catch(err){status.textContent=err.message;toast(err.message)}finally{providerCheckButton.disabled=false}});const draftButton=$('#generateTranslationDrafts');if(draftButton)draftButton.addEventListener('click',generateTranslationDrafts);
function openProduct(p){editingId=p?.id||null;editingOriginal=p?JSON.parse(JSON.stringify(p)):null;const f=$('#productForm');f.reset();f.elements.id.value=p?.id||'';f.elements.name.value=p?.name||'';f.elements.description.value=p?.description||'';f.elements.price.value=p?.price??'';f.elements.currency.value=p?.currency||'USD';f.elements.category.innerHTML=categoryOptions(p?.category||categories[0]?.name||'Pressure');updateSubcategoryOptions(f.elements.category.value,p?.subcategory||categories.find(c=>c.name===f.elements.category.value)?.subcategories?.[0]||'');f.elements.group.value=p?.group||'';f.elements.skusJson.value=p?.skus?.length?JSON.stringify(p.skus,null,2):'';if(typeof window.kejunLoadSkuGroups==='function')window.kejunLoadSkuGroups(p?.skuGroups||[]);f.elements.image.value=p?.image||'';f.elements.manualUrl.value=p?.manualUrl||'';f.elements.videoUrl.value=p?.videoUrl||'';f.elements.supportUrl.value=p?.supportUrl||'';f.elements.source.value=p?.source||'';f.elements.notes.value=p?.notes||'';f.elements.published.checked=p?.published!==false;renderSpecRows(p?.specs||{});renderTranslationEditor(p?.translations||{},p?.specs||{});updateImagePreview();$('#dialogTitle').textContent=p?'Edit product':'Add product';$('#productError').textContent='';$('#productDialog').showModal()}
$('#productForm').elements.category.onchange=()=>updateSubcategoryOptions($('#productForm').elements.category.value,'');$('#imagePath').oninput=updateImagePreview;function updateImagePreview(){const path=$('#imagePath').value.trim();$('#imagePreview').src=path?('/'+path.replace(/^\//,'')):'/assets/p4_i1_400x400.png';$('#imagePreview').onerror=()=>{$('#imagePreview').src='/assets/p4_i1_400x400.png'}}
$('#imageFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){$('#productError').textContent='Image must be 5 MB or smaller.';e.target.value='';return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){$('#productError').textContent='Please use PNG, JPG or WebP.';e.target.value='';return}try{$('#productError').textContent='Uploading image…';const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const result=await api('/api/images',{method:'POST',body:JSON.stringify({data})});$('#imagePath').value=result.path;updateImagePreview();$('#productError').textContent='Image uploaded. Save the product to apply it.'}catch(err){$('#productError').textContent=err.message}};
$('#manualFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.type!=='application/pdf'||file.size>20*1024*1024){$('#productError').textContent='Please choose a PDF no larger than 20 MB.';e.target.value='';return}try{$('#productError').textContent='Uploading PDF…';const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const result=await api('/api/resources/upload',{method:'POST',body:JSON.stringify({filename:file.name,mime:file.type,data})});$('#productForm').elements.manualUrl.value=result.path;$('#productError').textContent='Manual uploaded. Save the product to publish its link.'}catch(err){$('#productError').textContent=err.message}};
$('#addSpec').onclick=()=>{const div=document.createElement('div');div.innerHTML=specRow('','');const row=div.firstElementChild;$('#specEditor').append(row);row.querySelector('[data-remove-spec]').onclick=()=>{row.remove();refreshTranslationSpecFields()};row.querySelectorAll('input').forEach(el=>el.addEventListener('change',refreshTranslationSpecFields));refreshTranslationSpecFields()};function currentSpecsFromEditor(){const out={};$('#specEditor').querySelectorAll('.spec-edit-row').forEach(r=>{const k=r.querySelector('[data-spec-key]').value.trim(),v=r.querySelector('[data-spec-value]').value.trim();if(k&&v)out[k]=v});return out}function refreshTranslationSpecFields(){try{const current=collectProductTranslations(editingId?(products.find(x=>x.id===editingId)?.translations||{}):{});renderTranslationEditor(current,currentSpecsFromEditor())}catch(_){renderTranslationEditor(editingId?(products.find(x=>x.id===editingId)?.translations||{}):{},currentSpecsFromEditor())}}$('#closeDialog').onclick=$('#cancelDialog').onclick=()=>$('#productDialog').close();
async function saveProductForm(){if(typeof window.kejunSyncSkuBeforeSave==='function'&&!window.kejunSyncSkuBeforeSave())return false;const f=$('#productForm');const name=f.elements.name.value.trim();const specs={};$('#specEditor').querySelectorAll('.spec-edit-row').forEach(r=>{const k=r.querySelector('[data-spec-key]').value.trim(),v=r.querySelector('[data-spec-value]').value.trim();if(k&&v)specs[k]=v});let skus=[];try{skus=f.elements.skusJson.value.trim()?JSON.parse(f.elements.skusJson.value):[]}catch(_){$('#productError').textContent='SKU variants must be valid JSON.';return false}if(!Array.isArray(skus)){ $('#productError').textContent='SKU variants must be a JSON array.';return false}const skuIds=new Set();for(const sku of skus){if(!sku||!String(sku.id||'').trim()||!String(sku.name||'').trim()||!Number.isFinite(Number(sku.price))||Number(sku.price)<=0||String(sku.currency||'USD').toUpperCase()!=='USD'){ $('#productError').textContent='每种规格组合必须填写唯一 ID、组合名称、正数价格，币种必须为 USD。';return false}if(sku.attributes!==undefined&&(!sku.attributes||typeof sku.attributes!=='object'||Array.isArray(sku.attributes)||Object.entries(sku.attributes).some(([k,v])=>!String(k).trim()||!String(v).trim()))){$('#productError').textContent='attributes 必须是规格名称与选项值组成的对象。';return false}if(typeof sku.price!=='number'){$('#productError').textContent='SKU 价格必须填写 JSON 数字，不能使用字符串或布尔值。';return false}if(sku.image!==undefined&&sku.image!==null&&sku.image!==''){if(typeof sku.image!=='string'||sku.image.length>1000||/^[\s]*(?:javascript|data|vbscript):/i.test(sku.image)||/[<>]/.test(sku.image)){$('#productError').textContent='SKU 图片路径不安全或过长，请检查图片地址。';return false}}if(sku.inventoryQuantity!==undefined&&typeof sku.inventoryQuantity!=='number'){$('#productError').textContent='SKU 库存必须填写 JSON 数字，不能使用字符串或布尔值。';return false}sku.id=String(sku.id).trim();sku.name=String(sku.name).trim();if(!Number.isFinite(Number(sku.price))||Number(sku.price)>10000000||Math.abs(Math.round(Number(sku.price)*100)-Number(sku.price)*100)>1e-7){$('#productError').textContent='SKU 价格必须为不超过 10000000 的正数，最多两位小数。';return false}if(sku.inventoryQuantity!==undefined&&(!Number.isSafeInteger(Number(sku.inventoryQuantity))||Number(sku.inventoryQuantity)<0||String(sku.inventoryQuantity).trim()==='')){$('#productError').textContent='SKU 库存必须是非负整数。';return false}sku.price=Number(sku.price);sku.currency='USD';if(skuIds.has(sku.id)){ $('#productError').textContent='SKU IDs must be unique within a product.';return false}skuIds.add(sku.id)}let translations;try{translations=collectProductTranslations(editingId?(products.find(x=>x.id===editingId)?.translations||{}):{})}catch(err){$('#productError').textContent=err.message;return false}const p={id:editingId||slug(name),name,model:name,category:f.elements.category.value,subcategory:f.elements.subcategory.value,group:f.elements.group.value.trim(),skus,skuGroups:typeof window.kejunGetSkuGroups==='function'?window.kejunGetSkuGroups():[],description:f.elements.description.value.trim(),price:f.elements.price.value.trim(),currency:f.elements.currency.value||'USD',image:f.elements.image.value.trim()||'assets/p4_i1_400x400.png',manualUrl:f.elements.manualUrl.value.trim(),videoUrl:f.elements.videoUrl.value.trim(),supportUrl:f.elements.supportUrl.value.trim(),specs,translations,source:f.elements.source.value.trim(),notes:f.elements.notes.value.trim(),published:f.elements.published.checked};if(!p.group){$('#productError').textContent='Please enter a product group/series.';return false}if(products.some(x=>x.id===p.id)&&!editingId)p.id=slug(name)+'-'+Date.now().toString(36);try{if(editingId){await api('/api/products/'+encodeURIComponent(editingId),{method:'PUT',body:JSON.stringify({product:p,expected:editingOriginal})});products=products.map(x=>x.id===editingId?p:x)}else{await api('/api/products',{method:'POST',body:JSON.stringify({product:p})});products=[p,...products]}products=await api('/api/products');$('#productDialog').close();renderProducts();toast('Product saved. Public catalogue updated.')}catch(err){$('#productError').textContent=err.message;throw err}return true}
