function renderTaxonomy(){if(!categories.length)categories=[];selectedMajor=Math.min(selectedMajor,categories.length-1);$('#majorList').innerHTML=categories.map((c,i)=>`<button class="tax-pick ${i===selectedMajor?'active':''}" data-major-index="${i}">${esc(c.name)} <span class="count"> · ${(c.subcategories||[]).length} subcategories</span></button>`).join('');$('#majorList').querySelectorAll('[data-major-index]').forEach(b=>b.onclick=()=>{selectedMajor=Number(b.dataset.majorIndex);renderTaxonomy()});const c=categories[selectedMajor];if(!c){$('#taxSubTitle').textContent='Select or add a category';$('#renameMajorName').value='';$('#subcategoryList').innerHTML='';return}$('#taxSubTitle').textContent=c.name+' · Subcategories';$('#renameMajorName').value=c.name;$('#subcategoryList').innerHTML=(c.subcategories||[]).map((s,i)=>`<div class="tax-row"><input data-sub-index="${i}" value="${esc(s)}"><button class="smallbtn danger" data-delete-sub="${i}">Delete</button></div>`).join('');$('#subcategoryList').querySelectorAll('[data-delete-sub]').forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.deleteSub);if(!confirm('Remove this subcategory from the navigation? Products already assigned to it will remain saved but should be reassigned.'))return;c.subcategories.splice(idx,1);saveTaxonomy()});$('#subcategoryList').querySelectorAll('[data-sub-index]').forEach(inp=>inp.onchange=async()=>{const idx=Number(inp.dataset.subIndex),val=inp.value.trim(),old=c.subcategories[idx];if(!val||val===old)return;try{await api('/api/catalogue/taxonomy',{method:'PATCH',headers:{'If-Match':categoriesETag,'X-Product-Revision':productsETag},body:JSON.stringify({type:'sub',category:c.name,previous:old,next:val})});[categories,products]=await Promise.all([api('/api/categories'),api('/api/products')]);renderTaxonomy();renderProducts();toast('二级分类及相关产品已同步更新。')}catch(e){try{[categories,products]=await Promise.all([api('/api/categories'),api('/api/products')]);renderTaxonomy();renderProducts()}catch(_){}$('#taxonomyMessage').textContent=e.message}});const groupHost=$('#productGroupVisuals');if(groupHost){const groupMap=new Map();products.forEach(p=>{const key=[p.category||'',p.subcategory||'',p.group||'Other products'].join('|||');if(!groupMap.has(key))groupMap.set(key,[]);groupMap.get(key).push(p)});groupHost.innerHTML=[...groupMap.entries()].map(([key,items])=>{const [cat,sub,group]=key.split('|||');const p=items[0],groupImg=String(settings.productGroupImages?.[key]||p.image||'assets/p4_i1_400x400.png');return `<article style="border:1px solid #e2e8f0;border-radius:10px;padding:10px;background:#fff;min-width:0"><div style="height:110px;background:#f8fafc;border:1px solid #edf0f3;border-radius:7px;display:flex;align-items:center;justify-content:center;margin-bottom:9px"><img src="/${esc(groupImg.replace(/^\//,''))}" alt="${esc(p.name||p.model||group)}" style="max-width:100%;max-height:100%;object-fit:contain" onerror="this.onerror=null;this.src='/assets/p4_i1_400x400.png'"></div><strong style="display:block;overflow-wrap:anywhere">${esc(group)}</strong><div class="subtext">${esc(cat)} / ${esc(sub)}</div><div class="subtext">${items.length} 个产品：${esc(items.slice(0,3).map(x=>x.model||x.name).join('、'))}${items.length>3?'…':''}</div><button class="smallbtn" type="button" data-group-edit="${esc(p.id)}" style="margin-top:8px">编辑代表产品</button><label class="smallbtn" style="margin-top:8px;display:inline-block;cursor:pointer">上传独立分组图片<input type="file" data-group-upload="${esc(key)}" accept="image/png,image/jpeg,image/webp" style="display:none"></label>${settings.productGroupImages?.[key]?`<button class="smallbtn" type="button" data-group-image-reset="${esc(key)}">恢复产品默认图</button>`:''}</article>`}).join('')||'<p class="admin-subtitle">暂无产品分组。</p>';groupHost.querySelectorAll('[data-group-edit]').forEach(b=>b.onclick=()=>openProduct(products.find(x=>x.id===b.dataset.groupEdit)));groupHost.querySelectorAll('[data-group-upload]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const info=$('#taxonomyMessage');if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){info.textContent='图片必须为 PNG/JPG/WebP，且不超过 5MB。';return}info.textContent='正在上传产品分组图片…';try{const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});const uploaded=await api('/api/images',{method:'POST',body:JSON.stringify({data})});const next={...(settings.productGroupImages||{}),[input.dataset.groupUpload]:uploaded.path};await api('/api/settings',{method:'PUT',body:JSON.stringify({productGroupImages:next})});settings.productGroupImages=next;renderTaxonomy();$('#taxonomyMessage').textContent='分组图片保存成功，不影响产品主图。';}catch(e){info.textContent='上传或保存失败：'+e.message}});groupHost.querySelectorAll('[data-group-image-reset]').forEach(button=>button.onclick=async()=>{try{const next={...(settings.productGroupImages||{})};delete next[button.dataset.groupImageReset];await api('/api/settings',{method:'PUT',body:JSON.stringify({productGroupImages:next})});settings.productGroupImages=next;renderTaxonomy();$('#taxonomyMessage').textContent='已恢复该分组的默认产品图片。'}catch(e){$('#taxonomyMessage').textContent='恢复失败：'+e.message}});}$('#taxonomyMessage').textContent='';}
async function saveTaxonomy(updateProducts=false){try{await api('/api/categories',{method:'PUT',body:JSON.stringify(categories)});if(updateProducts)await api('/api/products',{method:'PUT',body:JSON.stringify(products)});renderTaxonomy();renderProducts();toast('Category structure saved')}catch(e){try{[categories,products]=await Promise.all([api('/api/categories'),api('/api/products')]);renderTaxonomy();renderProducts()}catch(_){}$('#taxonomyMessage').textContent=e.message}}
