function renderInquiries(){if(!inquiries.length){$('#inquiryList').innerHTML='<div class="empty">No quote requests received yet.</div>';$('#newCount').textContent='';return}$('#inquiryList').innerHTML=inquiries.map(i=>`<article class="inquiry"><div><h3>${esc(i.name)} · ${esc(i.company)}</h3><div class="meta">${esc(i.email)} ${i.phone?' · '+esc(i.phone):''} · ${new Date(i.createdAt).toLocaleString()} · ${esc(i.status||'New')}</div><div class="message">${esc([i.type&&'Type: '+i.type,i.source&&'Source: '+i.source,i.sourceUrl&&'Source URL: '+i.sourceUrl,i.category&&'Product family: '+i.category,i.model&&'Model: '+i.model,i.productName&&'Product: '+i.productName,i.productId&&'Product ID: '+i.productId,i.quantity&&'Quantity: '+i.quantity,i.items?.length&&'Items: '+i.items.map(x=>`${x.model||x.name} [${x.skuId||''}] x${x.qty} @ ${x.unitPrice??'quote'} ${x.currency||'USD'}`).join('; '),i.country&&'Destination: '+i.country,i.message].filter(Boolean).join('\n'))}</div></div><div class="right"><select data-status="${esc(i.id)}"><option ${i.status==='New'?'selected':''}>New</option><option ${i.status==='In progress'?'selected':''}>In progress</option><option ${i.status==='Replied'?'selected':''}>Replied</option><option ${i.status==='Closed'?'selected':''}>Closed</option></select><button class="smallbtn danger" data-remove="${esc(i.id)}">Delete</button></div></article>`).join('');$('#inquiryList').querySelectorAll('[data-status]').forEach(s=>s.onchange=async()=>{await api('/api/inquiries/'+encodeURIComponent(s.dataset.status),{method:'PATCH',body:JSON.stringify({status:s.value})});inquiries.find(i=>i.id===s.dataset.status).status=s.value;renderInquiries()});$('#inquiryList').querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this inquiry?')){await api('/api/inquiries/'+encodeURIComponent(b.dataset.remove),{method:'DELETE'});inquiries=inquiries.filter(i=>i.id!==b.dataset.remove);renderInquiries()}});$('#newCount').textContent=inquiries.filter(i=>i.status==='New').length||''}async function loadInquiries(){try{inquiries=await api('/api/inquiries');renderInquiries()}catch(e){toast(e.message)}}$('#refreshInquiries').onclick=loadInquiries;
function renderBankTransfers(){const list=$('#bankTransferList');if(!list)return;$('#bankTransferCount').textContent=bankTransfers.filter(x=>x.status==='Awaiting verification').length||'';const paid=bankTransfers.filter(x=>x.status==='Paid').length;const pending=bankTransfers.filter(x=>x.status==='Awaiting payment'||x.status==='Awaiting verification').length;const receiptTotals={};bankTransfers.filter(x=>x.status==='Paid').forEach(x=>{const c=x.currency||'USD';receiptTotals[c]=(receiptTotals[c]||0)+Number(x.receivedAmount||0)});const totalsLabel=Object.entries(receiptTotals).map(([c,n])=>c+' '+n.toFixed(2)).join(' · ')||'No receipts recorded';$('#orderStats').innerHTML=`<span class="spec">Total orders: ${bankTransfers.length}</span><span class="spec">Paid: ${paid}</span><span class="spec">Pending: ${pending}</span><span class="spec">Recorded receipts: ${esc(totalsLabel)}</span><button class="secondary" id="exportOrders">Export CSV</button>`;$('#exportOrders').onclick=()=>{const cols=['id','createdAt','status','currency','amount','buyer.name','buyer.company','buyer.email','buyer.phone','items','remittanceDate','receivedAmount','receivedDate','shippingCarrier','trackingNumber','trackingUrl','shippedDate','deliveryStatus'];const val=(x,k)=>k==='items'?(x.items||[]).map(i=>`${i.model} x${i.qty} @ ${i.unitPrice??'quote'}`).join('; '):k.startsWith('buyer.')?x.buyer?.[k.slice(6)]||'':x[k]??'';const csv=[cols.join(','),...bankTransfers.map(x=>cols.map(k=>'\"'+String(val(x,k)).replace(/\"/g,'\"\"')+'\"').join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='kejun-orders.csv';a.click();URL.revokeObjectURL(a.href)};if(!bankTransfers.length){list.innerHTML='<div class="empty">No bank transfer orders yet.</div>';return}const statuses=['Awaiting payment','Awaiting verification','Paid','Refunded','Cancelled'];list.innerHTML=bankTransfers.map(x=>`<article class="inquiry"><div><h3>${esc(x.id)} · ${esc(x.amount?x.currency+' '+x.amount:'Price to be confirmed')} <span class="badge ${x.status==='Paid'?'':'off'}">${esc(x.status)}</span></h3><div class="meta">Created: ${new Date(x.createdAt).toLocaleString()} · Method: Bank Transfer (T/T)</div><div class="message">Buyer: ${esc(x.buyer?.name)} · ${esc(x.buyer?.company)} · ${esc(x.buyer?.email)}${x.buyer?.phone?' · '+esc(x.buyer.phone):''}<br>Items: ${esc((x.items||[]).map(i=>i.model+' × '+i.qty).join('; '))}<br>Remittance date: ${esc(x.remittanceDate||'—')} · Received: ${esc(x.receivedAmount||'—')} ${esc(x.currency||'USD')} · Received date: ${esc(x.receivedDate||'—')}<br>Remittance proof: ${x.proofPath?`<a href="/api/bank-transfers/${encodeURIComponent(x.id)}/proof" target="_blank" rel="noopener">Download private receipt</a>`:'Not uploaded'}<br>Order notes: ${esc(x.orderNotes||'—')}<br>Internal note: ${esc(x.adminNote||'—')}</div></div><div class="right"><label class="admin-subtitle">Payment status<select data-bank-status="${esc(x.id)}">${statuses.map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="admin-subtitle">Remittance date<input type="date" data-remit="${esc(x.id)}" value="${esc(x.remittanceDate||'')}"></label><label class="admin-subtitle">Actual received amount<input type="number" min="0" step="0.01" data-received="${esc(x.id)}" value="${esc(x.receivedAmount||'')}" placeholder="USD received"></label><label class="admin-subtitle">Received date<input type="date" data-received-date="${esc(x.id)}" value="${esc(x.receivedDate||'')}"></label><label class="admin-subtitle">Shipping carrier<input data-carrier="${esc(x.id)}" value="${esc(x.shippingCarrier||'')}" placeholder="DHL / FedEx / UPS / freight forwarder"></label><label class="admin-subtitle">Tracking number<input data-tracking="${esc(x.id)}" value="${esc(x.trackingNumber||'')}" placeholder="Tracking number"></label><label class="admin-subtitle">Tracking URL<input data-tracking-url="${esc(x.id)}" value="${esc(x.trackingUrl||'')}" placeholder="Carrier tracking link"></label><label class="admin-subtitle">Shipped date<input type="date" data-shipped="${esc(x.id)}" value="${esc(x.shippedDate||'')}"></label><label class="admin-subtitle">Delivery status<select data-delivery="${esc(x.id)}">${['Not shipped','Preparing shipment','Shipped','In transit','Delivered','Exception'].map(s=>`<option ${x.deliveryStatus===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="admin-subtitle">Internal note<textarea data-bank-note="${esc(x.id)}" rows="2">${esc(x.adminNote||'')}</textarea></label><button class="smallbtn" data-bank-save="${esc(x.id)}">Save record</button></div></article>`).join('');list.querySelectorAll('[data-bank-save]').forEach(b=>b.onclick=async()=>{const id=b.dataset.bankSave;try{const payload={status:list.querySelector(`[data-bank-status="${id}"]`).value,remittanceDate:list.querySelector(`[data-remit="${id}"]`).value,receivedAmount:list.querySelector(`[data-received="${id}"]`).value,receivedDate:list.querySelector(`[data-received-date="${id}"]`).value,adminNote:list.querySelector(`[data-bank-note="${id}"]`).value,shippingCarrier:list.querySelector(`[data-carrier="${id}"]`).value,trackingNumber:list.querySelector(`[data-tracking="${id}"]`).value,trackingUrl:list.querySelector(`[data-tracking-url="${id}"]`).value,shippedDate:list.querySelector(`[data-shipped="${id}"]`).value,deliveryStatus:list.querySelector(`[data-delivery="${id}"]`).value};if(payload.status==='Paid'&&(!payload.receivedAmount||!payload.receivedDate)){toast('Enter actual received amount and date before marking Paid.');return}const out=await api('/api/bank-transfers/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify(payload)});bankTransfers=bankTransfers.map(x=>x.id===id?out.record:x);renderBankTransfers();toast('Bank transfer record saved')}catch(e){toast(e.message)}})}async function loadBankTransfers(){try{bankTransfers=await api('/api/bank-transfers');renderBankTransfers()}catch(e){toast(e.message)}}const rbt=$('#refreshBankTransfers');if(rbt)rbt.onclick=loadBankTransfers;
function fillSettings(){const f=$('#settingsForm');Object.keys(settings).forEach(k=>{if(f.elements[k])f.elements[k].value=settings[k]||''})}$('#settingsForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=Object.fromEntries(new FormData(f).entries());try{await api('/api/settings',{method:'PUT',body:JSON.stringify(b)});settings={...settings,...b};$('#settingsMessage').textContent='Saved.';toast('Settings saved')}catch(err){$('#settingsMessage').textContent=err.message}};$('#productDialog').addEventListener('click',e=>{if(e.target===$('#productDialog'))$('#productDialog').close()});init().catch(e=>{console.error(e);$('#status').textContent='Connection error';$('#gate').classList.remove('hidden');$('#gateError').textContent=e.message});
function renderPayments(){const list=$('#paymentList');if(!list)return;$('#paymentCount').textContent=payments.filter(p=>p.status==='Completed').length||'';if(!payments.length){list.innerHTML='<div class="empty">No PayPal payment records yet.</div>';return}list.innerHTML=payments.map(p=>`<article class="inquiry"><div><h3>${esc(p.id)} · ${esc(p.currency)} ${esc(p.captureAmount||p.amount)} <span class="badge ${p.status==='Completed'?'':'off'}">${esc(p.status||'Created')}</span></h3><div class="meta">Created: ${new Date(p.createdAt).toLocaleString()}${p.paidAt?' · Paid: '+new Date(p.paidAt).toLocaleString():''}</div><div class="message">Buyer: ${esc(p.buyer?.name)} · ${esc(p.buyer?.company)} · ${esc(p.buyer?.email)}${p.buyer?.phone?' · '+esc(p.buyer.phone):''}<br>Items: ${esc((p.items||[]).map(x=>x.model+' × '+x.qty).join('; '))}<br>PayPal order: ${esc(p.paypalOrderId||'—')} · Capture: ${esc(p.paypalCaptureId||'—')}${p.payerEmail?' · Payer email: '+esc(p.payerEmail):''}</div></div></article>`).join('')}async function loadPayments(){try{payments=await api('/api/payments');renderPayments()}catch(e){toast(e.message)}}const rp=$('#refreshPayments');if(rp)rp.onclick=loadPayments;


// CRM combines all recorded website contacts into one profile per email address.
function normEmail(v){return String(v||'').trim().toLowerCase()}
function loadCRM(){Promise.all([api('/api/inquiries'),api('/api/bank-transfers'),api('/api/payments'),api('/api/crm')]).then(([iq,bt,pp,profiles])=>{inquiries=iq;bankTransfers=bt;payments=pp;crmProfiles=profiles;renderCRM()}).catch(e=>toast(e.message))}
function buildCRM(){const map=new Map();const get=(buyer,createdAt,source,items=[],amount=null,currency='USD',status='',receivedAmount=null)=>{const email=normEmail(buyer?.email);if(!email)return;let c=map.get(email);if(!c){c={email,name:buyer?.name||'',company:buyer?.company||'',phone:buyer?.phone||'',country:buyer?.country||'',firstSeen:createdAt||'',lastSeen:createdAt||'',sources:new Set(),orders:[],models:new Set(),amountsByCurrency:{},receivedByCurrency:{},currency:currency||'USD'};map.set(email,c)};for(const k of ['name','company','phone','country'])if(!c[k]&&buyer?.[k])c[k]=buyer[k];if(createdAt&&(!c.firstSeen||createdAt<c.firstSeen))c.firstSeen=createdAt;if(createdAt&&(!c.lastSeen||createdAt>c.lastSeen))c.lastSeen=createdAt;c.sources.add(source);if(source!=='Inquiry'){const id=source==='Bank transfer'?`BT:${status||''}:${createdAt}`:`PP:${status||''}:${createdAt}`;c.orders.push({source,createdAt,amount,currency,status,id,items:items||[]});if(source==='Bank transfer'&&receivedAmount!==null&&receivedAmount!==''&&Number.isFinite(Number(receivedAmount))){const rc=String(currency||'USD').toUpperCase();c.receivedByCurrency[rc]=(c.receivedByCurrency[rc]||0)+Number(receivedAmount);}if(amount!==null&&amount!==''&&Number.isFinite(Number(amount))){const cc=String(currency||'USD').toUpperCase();c.amountsByCurrency[cc]=(c.amountsByCurrency[cc]||0)+Number(amount);}(items||[]).forEach(i=>c.models.add(i.model||i.name||''))}};inquiries.forEach(i=>get({name:i.name,company:i.company,email:i.email,phone:i.phone,country:i.country},i.createdAt,'Inquiry',[],null,'',i.status));bankTransfers.forEach(o=>get(o.buyer,o.createdAt,'Bank transfer',o.items,o.amount,o.currency,o.status,o.receivedAmount));payments.forEach(o=>get(o.buyer,o.createdAt,'PayPal',o.items,o.captureAmount||o.amount,o.captureCurrency||o.currency,o.status));return [...map.values()].map(c=>{const p=crmProfiles.find(x=>normEmail(x.email)===c.email)||{};return {...c,sources:[...c.sources].join(', '),orders:c.orders.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))),stage:p.stage||((c.orders.length)?'Customer':'Lead'),owner:p.owner||'',nextFollowUp:p.nextFollowUp||'',notes:p.notes||''}}).sort((a,b)=>String(b.lastSeen).localeCompare(String(a.lastSeen)))}
function renderCRM(){const all=buildCRM(),q=($('#crmSearch')?.value||'').toLowerCase(),stage=$('#crmStageFilter')?.value||'';const rows=all.filter(c=>(!stage||c.stage===stage)&&[c.name,c.company,c.email,c.phone,c.country,...c.models].join(' ').toLowerCase().includes(q));$('#crmCount').textContent=all.filter(c=>c.stage==='Lead'||c.stage==='Contacted').length||'';$('#crmSummary').textContent=`${all.length} contacts · ${all.filter(c=>c.orders.length).length} with orders`;const list=$('#crmList');if(!rows.length){list.innerHTML='<div class="empty">No matching customer profiles yet. Profiles appear automatically when a customer submits a quote request or order.</div>';return}list.innerHTML=rows.map(c=>`<article class="inquiry"><div><h3>${esc(c.company||c.name||'Unknown company')} <span class="badge ${c.orders.length?'':'off'}">${esc(c.stage)}</span></h3><div class="meta">${esc(c.name)} · ${esc(c.email)}${c.phone?' · WhatsApp/Phone: '+esc(c.phone):''}${c.country?' · '+esc(c.country):''}</div><div class="message">First contact: ${esc(c.firstSeen?new Date(c.firstSeen).toLocaleDateString():'—')} · Last activity: ${esc(c.lastSeen?new Date(c.lastSeen).toLocaleString():'—')}<br>Sources: ${esc(c.sources)} · Orders recorded: ${c.orders.length} · Recorded order value: ${esc(Object.entries(c.amountsByCurrency).map(([cc,n])=>cc+' '+n.toFixed(2)).join(' · ')||'Not priced')}<br>Recorded bank receipts: ${esc(Object.entries(c.receivedByCurrency||{}).map(([cc,n])=>cc+' '+n.toFixed(2)).join(' · ')||'No confirmed receipts recorded')}<br>Products/models: ${esc([...c.models].filter(Boolean).join(', ')||'No products recorded')}<br>Recent history: ${esc(c.orders.slice(0,5).map(o=>`${o.source} ${o.createdAt?new Date(o.createdAt).toLocaleDateString():''} ${o.currency||''} ${o.amount??'RFQ'} [${o.status||'—'}]`).join(' | ')||'No orders yet')}</div></div><div class="right"><label class="admin-subtitle">Relationship stage<select data-crm-stage="${esc(c.email)}">${['Lead','Contacted','Quoted','Negotiation','Customer','Repeat customer','Inactive'].map(s=>`<option ${s===c.stage?'selected':''}>${s}</option>`).join('')}</select></label><label class="admin-subtitle">Account owner<input data-crm-owner="${esc(c.email)}" value="${esc(c.owner)}" placeholder="Sales owner"></label><label class="admin-subtitle">Next follow-up<input type="date" data-crm-follow="${esc(c.email)}" value="${esc(c.nextFollowUp)}"></label><label class="admin-subtitle">Customer notes / next action<textarea data-crm-notes="${esc(c.email)}" rows="3" placeholder="Needs, quotation sent, next contact, negotiation history">${esc(c.notes)}</textarea></label><button class="smallbtn" data-crm-save="${esc(c.email)}">Save CRM profile</button></div></article>`).join('');list.querySelectorAll('[data-crm-save]').forEach(b=>b.onclick=async()=>{const email=b.dataset.crmSave;try{const payload={stage:list.querySelector(`[data-crm-stage="${CSS.escape(email)}"]`).value,owner:list.querySelector(`[data-crm-owner="${CSS.escape(email)}"]`).value,nextFollowUp:list.querySelector(`[data-crm-follow="${CSS.escape(email)}"]`).value,notes:list.querySelector(`[data-crm-notes="${CSS.escape(email)}"]`).value};await api('/api/crm/'+encodeURIComponent(email),{method:'PATCH',body:JSON.stringify(payload)});crmProfiles=await api('/api/crm');toast('CRM profile saved');renderCRM()}catch(e){toast(e.message)}})}

let emailOutboxItems=[];
async function loadEmailOutbox(){
  const status=$('#emailOutboxStatus'),list=$('#emailOutboxList');
  status.textContent='Loading email queue…';
  try{
    const result=await api('/api/email-outbox');
    emailOutboxItems=result.items||[];
    const counts=emailOutboxItems.reduce((a,x)=>(a[x.status]=(a[x.status]||0)+1,a),{});
    const count=$('#emailOutboxCount');
    if(count)count.textContent=counts.failed?String(counts.failed):'';
    status.textContent=`SMTP configuration: ${result.configured?'configured':'not complete'} · Showing ${emailOutboxItems.length} of ${result.total} notifications · Pending: ${counts.pending||0} · Sending: ${counts.sending||0} · Sent: ${counts.sent||0} · Failed: ${counts.failed||0}`;
    if(!emailOutboxItems.length){list.innerHTML='<div class="empty">No email notifications have been queued yet.</div>';return}
    list.innerHTML=emailOutboxItems.map(x=>`<article class="inquiry"><div><h3>${esc(x.subject||'Qingke notification')} <span class="${x.status==='failed'?'danger':''}">[${esc(x.status)}]</span></h3><div class="meta">Queued: ${esc(x.createdAt?new Date(x.createdAt).toLocaleString():'—')} · Attempts: ${Number(x.attempts||0)}${x.sentAt?' · Sent: '+esc(new Date(x.sentAt).toLocaleString()):''}</div><div class="message">${esc(x.textPreview||'No preview available')}${x.lastError?'<p><strong>Last error:</strong> '+esc(x.lastError)+'</p>':''}${x.nextAttemptAt&&x.status==='pending'?'<p>Next attempt: '+esc(new Date(x.nextAttemptAt).toLocaleString())+'</p>':''}</div></div><div class="right">${['failed','pending'].includes(x.status)?`<button class="smallbtn" data-email-retry="${esc(x.id)}">Retry now</button>`:''}${x.messageId?`<small>Message ID: ${esc(x.messageId)}</small>`:''}</div></article>`).join('');
    list.querySelectorAll('[data-email-retry]').forEach(button=>button.addEventListener('click',async()=>{
      button.disabled=true;button.textContent='Queueing…';
      try{await api('/api/email-outbox/'+encodeURIComponent(button.dataset.emailRetry)+'/retry',{method:'POST',body:'{}'});toast('Email queued for retry');await loadEmailOutbox()}
      catch(e){toast(e.message);button.disabled=false;button.textContent='Retry now'}
    }));
  }catch(e){status.textContent='Could not load the email queue: '+e.message;list.innerHTML=''}
}
$('#refreshEmailOutbox')?.addEventListener('click',loadEmailOutbox);

$('#refreshCRM')?.addEventListener('click',loadCRM);$('#crmSearch')?.addEventListener('input',renderCRM);$('#crmStageFilter')?.addEventListener('change',renderCRM);$('#exportCRM')?.addEventListener('click',()=>{const rows=buildCRM();const cols=['name','company','email','phone','country','firstSeen','lastSeen','stage','owner','nextFollowUp','sources','orderCount','orderValueByCurrency','receivedByCurrency','models','notes'];const csv=[cols.join(','),...rows.map(c=>{const v={...c,orderCount:c.orders.length,models:[...c.models].join('; '),orderValueByCurrency:Object.entries(c.amountsByCurrency||{}).map(([cc,n])=>cc+' '+n.toFixed(2)).join(' | '),receivedByCurrency:Object.entries(c.receivedByCurrency||{}).map(([cc,n])=>cc+' '+n.toFixed(2)).join(' | ')};return cols.map(k=>'"'+String(v[k]??'').replace(/"/g,'""')+'"').join(',')})].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='kejun-crm-customers.csv';a.click();URL.revokeObjectURL(a.href)});
